-- Table data and edit fixture (M2-1, M2-2), PostgreSQL flavor. `{s}` is the schema created
-- for the run (dropped afterwards). Same logical tables on every engine: `kinds` (one column
-- per value kind, defaults, an identity), `composite` (two-column key), `Odd "Table"`
-- (identifiers that need quoting), `items` (unique, check, generated column), `child`
-- (foreign key), `keyless`, `uniq` (identity through a unique key), `items_view`.

CREATE TYPE {s}.mood AS ENUM ('sad', 'ok', 'happy');

CREATE TABLE {s}.kinds (
    id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    flag boolean,
    small smallint,
    big bigint,
    amount numeric(30,10),
    ratio double precision,
    label text,
    code varchar(10),
    raw bytea,
    day date,
    at_time time,
    local_at timestamp(6),
    at_tz timestamptz,
    span interval,
    ref uuid,
    doc jsonb,
    tags text[],
    spot point,
    mood {s}.mood,
    note text NOT NULL DEFAULT 'hello',
    created timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE {s}.composite (
    a integer NOT NULL,
    b varchar(10) NOT NULL,
    value text,
    PRIMARY KEY (a, b)
);

CREATE TABLE {s}."Odd ""Table""" (
    "id" integer PRIMARY KEY,
    "Select" text,
    "two words" text
);

CREATE TABLE {s}.items (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sku text NOT NULL CONSTRAINT items_sku_key UNIQUE,
    qty integer NOT NULL CONSTRAINT items_qty_check CHECK (qty >= 0),
    price numeric(10,2) NOT NULL DEFAULT 1,
    total numeric(12,2) GENERATED ALWAYS AS (qty * price) STORED
);

CREATE TABLE {s}.child (
    id integer PRIMARY KEY,
    item_id integer NOT NULL CONSTRAINT child_item_fkey REFERENCES {s}.items (id)
);

CREATE TABLE {s}.keyless (name text, value integer);

CREATE TABLE {s}.uniq (code text NOT NULL CONSTRAINT uniq_code_key UNIQUE, label text);

CREATE VIEW {s}.items_view AS SELECT id, sku FROM {s}.items;
